import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** WORLD role identity is separate from action rotations; original player and pair fences remain strict. */
public final class CompanionRoleIdentityMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",COM=P+"NativePlayerCommit",B=COM+"$Binding",M=P+"NativeStaticNpcMotion",T=P+"NativeCompanionTargets",S=T+"$Scope",A=P+"NativeAreaMaterialAction",C=A+"$Context",H=P+"NativeCompanionRoleIdentity";
 static ClassNode read(JarFile j,String name)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(name+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static AbstractInsnNode prev(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static MethodNode clone(MethodNode m,String name,String...extra){var q=new MethodNode(m.access,name,m.desc,null,m.exceptions.toArray(String[]::new));m.accept(q);if(extra.length>0){q.desc=m.desc.substring(0,m.desc.indexOf(')'))+String.join("",extra)+m.desc.substring(m.desc.indexOf(')'));for(var n:q.instructions){if(n instanceof VarInsnNode v&&v.var>=1)v.var+=extra.length;if(n instanceof IincInsnNode v&&v.var>=1)v.var+=extra.length;if(n instanceof FrameNode f){if(f.type!=F_NEW)throw new AssertionError("expanded frame");for(int i=extra.length-1;i>=0;i--)f.local.add(1,Type.getType(extra[i]).getInternalName());}}q.maxLocals+=extra.length;}return q;}
 static int allocations(MethodNode m,boolean desired){int count=0;for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode ctor&&ctor.getOpcode()==INVOKESPECIAL&&ctor.owner.equals("java/lang/Object")&&ctor.name.equals("<init>")){var dup=prev(n);var alloc=prev(dup);if(dup.getOpcode()!=DUP||!(alloc instanceof TypeInsnNode t&&t.getOpcode()==NEW&&t.desc.equals("java/lang/Object")))throw new AssertionError("owner allocation");var i=new InsnList();i.add(new VarInsnNode(ALOAD,desired?1:0));if(!desired)i.add(new MethodInsnNode(INVOKESTATIC,H,"nextRole","(L"+PC+";)Ljava/lang/Object;",false));m.instructions.insertBefore(alloc,i);m.instructions.remove(alloc);m.instructions.remove(dup);m.instructions.remove(ctor);count++;}return count;}
 static MethodNode wrapper(MethodNode m,String name,String desc){return new MethodNode(m.access,name,desc,null,m.exceptions.toArray(String[]::new));}
 static void patch(ClassNode c){
  if(c.name.equals(P+"BattleTimedStatus")){int count=0;for(var f:c.fields)if(f.name.equals("sourcePoisonLifecycle")){if((f.access&ACC_VOLATILE)!=0)throw new AssertionError("unexpected slot flags");f.access|=ACC_VOLATILE;count++;}if(count!=1)throw new AssertionError("existing role slot visibility");return;}
  if(c.name.equals(COM)){int owner=0,advance=0,assign=0,scene=0;for(var m:new ArrayList<>(c.methods)){
   if(m.name.equals("owner")){owner+=allocations(m,false);}
   if(m.name.equals("nativeStaticOriginalAdvance")){var q=clone(m,"nativeCompanionSceneOriginalAdvance","Ljava/lang/Object;");if(allocations(q,true)!=2)throw new AssertionError("scene allocation ports");c.methods.add(q);advance+=allocations(m,false);}
   if(m.name.equals("assign")){var q=clone(m,"nativeCompanionSceneAssign");int calls=0;for(var n:q.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(COM)&&v.name.equals("advance")){var i=new InsnList();i.add(new VarInsnNode(ALOAD,1));i.add(new VarInsnNode(ALOAD,2));q.instructions.insertBefore(v,i);v.owner=M;v.name="nativeCompanionSceneAdvance";v.desc="(L"+PC+";Ljava/lang/Object;Ljava/lang/String;)V";calls++;}if(calls!=1)throw new AssertionError("scene assign");c.methods.add(q);assign++;}
   if(m.name.equals("scene"))for(var n:m.instructions)if(n instanceof MethodInsnNode v&&v.owner.equals(COM)&&v.name.equals("assign")){v.name="nativeCompanionSceneAssign";scene++;}
  }if(owner!=1||advance!=2||assign!=1||scene!=1)throw new AssertionError("commit ports "+owner+" "+advance+" "+assign+" "+scene);return;}
  if(c.name.equals(M)){int count=0;for(var m:new ArrayList<>(c.methods))if(m.name.equals("advance")){var q=clone(m,"nativeCompanionSceneAdvance","Ljava/lang/Object;","Ljava/lang/String;");int calls=0;for(var n:q.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(COM)&&v.name.equals("nativeStaticOriginalAdvance")){var i=new InsnList();i.add(new VarInsnNode(ALOAD,1));i.add(new VarInsnNode(ALOAD,2));q.instructions.insertBefore(v,i);v.owner=H;v.name="advanceScene";v.desc="(L"+PC+";Ljava/lang/Object;Ljava/lang/String;)V";calls++;}if(calls!=1)throw new AssertionError("motion scene bridge");c.methods.add(q);count++;}if(count!=1)throw new AssertionError("motion root");return;}
  if(c.name.equals(T)){int npc=0,cast=0,pub=0;for(var m:new ArrayList<>(c.methods)){
   if(m.name.equals("npc")){m.name="nativeRoleOriginalNpc";var w=wrapper(m,"npc",m.desc);w.instructions.add(new VarInsnNode(ALOAD,0));w.instructions.add(new VarInsnNode(LLOAD,1));w.instructions.add(new MethodInsnNode(INVOKESTATIC,H,"npc",m.desc,false));w.instructions.add(new InsnNode(IRETURN));c.methods.add(w);npc++;}
   if(m.name.equals("cast"))for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(A)&&v.name.equals("run")){m.instructions.insertBefore(v,new VarInsnNode(ALOAD,3));v.name="nativeCompanionAreaCapturedRun";v.desc="(L"+PC+";IL"+P+"NativeSelfCastAction$Task;L"+C+";)V";cast++;}
   if(m.name.equals("publication"))for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode v&&v.owner.equals(B)&&v.name.equals("matches")){v.setOpcode(INVOKESTATIC);v.owner=H;v.name="actorBinding";v.desc="(L"+B+";L"+PC+";)Z";pub++;}
  }if(npc!=1||cast!=1||pub!=2)throw new AssertionError("target ports "+npc+" "+cast+" "+pub);return;}
  if(c.name.equals(S)){int count=0;for(var m:new ArrayList<>(c.methods))if(m.name.equals("owns")){m.name="nativeRoleOriginalOwns";var w=wrapper(m,"owns",m.desc);for(int i=0;i<3;i++)w.instructions.add(new VarInsnNode(ALOAD,i));w.instructions.add(new MethodInsnNode(INVOKESTATIC,H,"owns","(L"+S+";L"+C+";L"+PC+";)Z",false));w.instructions.add(new InsnNode(IRETURN));c.methods.add(w);count++;}if(count!=1)throw new AssertionError("scope root");return;}
  if(c.name.equals(P+"NativeCompanionPlacement$State")||c.name.equals(P+"NativeCompanionPlacement$Transition")){boolean state=c.name.endsWith("$State");int count=0;for(var m:new ArrayList<>(c.methods))if(m.name.equals(state?"role":"character")){String name=m.name;m.name=state?"nativeRoleOriginalRole":"nativeRoleOriginalCharacter";var w=wrapper(m,name,m.desc);w.instructions.add(new VarInsnNode(ALOAD,0));w.instructions.add(new VarInsnNode(ALOAD,1));w.instructions.add(new MethodInsnNode(INVOKESTATIC,H,state?"stateRole":"transitionCharacter","(L"+c.name+";L"+PC+";)Z",false));w.instructions.add(new InsnNode(IRETURN));c.methods.add(w);count++;}if(count!=1)throw new AssertionError("placement role port");return;}
  throw new AssertionError(c.name);
 }
 public static void main(String[]args)throws Exception{try(var j=new JarFile(args[1])){for(var name:List.of(COM,M,T,S,P+"BattleTimedStatus",P+"NativeCompanionPlacement$State",P+"NativeCompanionPlacement$Transition")){var c=read(j,name);patch(c);var expected=bytes(c);if(args[0].equals("splice")){var out=Path.of(args[2]).resolve(name+".class");Files.createDirectories(out.getParent());Files.write(out,expected);}else try(var candidate=new JarFile(args[2])){if(!Arrays.equals(expected,bytes(read(candidate,name))))throw new AssertionError(name);}}}System.out.println("PASS exact role/action allocations, WORLD scene/placement and frozen actor guards; player/pair binding implementations untouched");}
}
